//! Seq-related expression analysis utilities.
//!
//! Split from [`crate::expr`] to stay under the 500-line file limit.
//! Functions here detect Seq-specific patterns in `PureExpr` trees.

use trust_wp_core::formula::{PureExpr, PureExprDepthLimitedTraversalExt as _};

use crate::encoder::MAX_ENCODING_DEPTH;

/// Checks if an expression contains a Seq index method call on a `Final` receiver.
///
/// This detects the pattern generated by IndexMut extern spec postconditions:
/// `Final(View(var)).index_logic(idx) == value`. When this pattern is present,
/// the encoder's `try_synthesize_index_mut_seq_value` will fire and create
/// Array `store`/`select` operations, requiring Array theory support (at minimum
/// `QF_AUFLIA` instead of `QF_LIA`). (#1317)
pub(crate) fn expr_has_seq_index_on_final(expr: &PureExpr) -> bool {
    // fail-closed: `on_limit = true` assumes feature exists at depth limit
    expr.any_recursive_with_depth_limit(MAX_ENCODING_DEPTH, true, |e| {
        matches!(
            e,
            PureExpr::MethodCall { method, receiver, .. }
                if matches!(method.as_str(), "index_logic" | "index")
                    && receiver_contains_final(receiver)
        )
    })
}

/// Checks if an expression contains Seq method calls that trigger quantified
/// axioms (reverse, sum, contains, concat, subsequence, tail/pop operations).
///
/// These methods require `forall_with_triggers` axioms for soundness, so the
/// encoder must use a quantifier-capable logic (UFLIA or AUFLIA) instead of
/// QF_LIA. (#1581)
///
/// Note: push_back/push_front/push_front_ghost/set/len/index_logic/get use
/// concrete Array+Length encoding and don't strictly require quantified axioms,
/// but they do require the Array theory (store/select). However, Seq method
/// presence at all implies the uninterpreted Seq sort and UF applications are
/// needed, so we conservatively detect any Seq method call.
pub(crate) fn expr_has_seq_method_needing_quantifiers(expr: &PureExpr) -> bool {
    // fail-closed: `on_limit = true` assumes feature exists at depth limit
    expr.any_recursive_with_depth_limit(MAX_ENCODING_DEPTH, true, |e| {
        matches!(
            e,
            PureExpr::MethodCall { method, .. }
                if matches!(
                    method.as_str(),
                    "reverse" | "sum" | "contains" | "concat" | "subsequence"
                        | "ext_eq" | "push_back" | "push_front" | "push_front_ghost"
                        | "set" | "tail" | "pop_front" | "pop_back" | "to_owned_seq"
                        | "exchange" | "permutation_of"
                )
        ) || matches!(
            e,
            PureExpr::LogicFnCall { name, .. } if name == "seq"
        )
    })
}

/// Helper: checks if a receiver expression contains `Final` wrapping.
fn receiver_contains_final(expr: &PureExpr) -> bool {
    match expr {
        PureExpr::Final(_) => true,
        PureExpr::View(inner) | PureExpr::Old(inner) | PureExpr::Deref(inner) => {
            receiver_contains_final(inner)
        }
        _ => false,
    }
}
